#### Phase 2: Event-Driven Projections (4-6 weeks)

**Goal**: Implement asynchronous event-based read model updates

**Activities**:
1. Implement event publishing from write operations
2. Create projection service to consume events
3. Update read models asynchronously
4. Monitor projection lag

**Implementation**:
```csharp
// 1. Publish events from write operations
public class ClaimService
{
    private readonly ClaimRepository _writeRepo;
    private readonly IEventPublisher _eventPublisher;

    public async Task<Guid> ProcessClaim(ProcessClaimCommand command)
    {
        // Write to normalized model
        var claim = new Claim(command.ClaimId, command.ProviderId, command.Amount);
        await _writeRepo.SaveAsync(claim);

        // Publish domain event
        var evt = new ClaimProcessedEvent
        {
            EventId = Guid.NewGuid(),
            ClaimId = claim.ClaimId,
            ProviderId = claim.ProviderId,
            Amount = claim.Amount,
            ProcessedDate = DateTime.UtcNow,
            Timestamp = DateTime.UtcNow
        };
        await _eventPublisher.PublishAsync(evt);

        return claim.ClaimId;
    }
}

// 2. Consume events and update read model
public class ProviderRemittanceProjection : BackgroundService
{
    private readonly IServiceBusClient _serviceBus;
    private readonly ILogger<ProviderRemittanceProjection> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await _serviceBus.SubscribeAsync<ClaimProcessedEvent>(
            async (evt, cancellationToken) =>
            {
                await UpdateReadModel(evt);
            },
            stoppingToken);
    }

    private async Task UpdateReadModel(ClaimProcessedEvent evt)
    {
        using var scope = _serviceProvider.CreateScope();
        var readDb = scope.ServiceProvider.GetRequiredService<ReadDbContext>();

        // Idempotency check
        if (await readDb.ProcessedEvents.AnyAsync(e => e.EventId == evt.EventId))
        {
            _logger.LogInformation("Event {EventId} already processed", evt.EventId);
            return;
        }

        // Update read model
        var provider = await readDb.ProviderRemittanceReadModel
            .FirstOrDefaultAsync(p => p.ProviderId == evt.ProviderId);

        if (provider == null)
        {
            provider = new ProviderRemittanceReadModel
            {
                ProviderId = evt.ProviderId,
                RemittanceCount = 0,
                TotalAmount = 0
            };
            readDb.ProviderRemittanceReadModel.Add(provider);
        }

        provider.RemittanceCount++;
        provider.TotalAmount += evt.Amount;
        provider.LastRemittanceDate = evt.ProcessedDate;
        provider.LastUpdated = DateTime.UtcNow;

        // Track processed event
        readDb.ProcessedEvents.Add(new ProcessedEvent
        {
            EventId = evt.EventId,
            ProcessedAt = DateTime.UtcNow
        });

        await readDb.SaveChangesAsync();

        _logger.LogInformation(
            "Updated read model for provider {ProviderId} from event {EventId}",
            evt.ProviderId, evt.EventId);
    }
}

// 3. Monitor projection lag
public class ProjectionHealthCheck : IHealthCheck
{
    private readonly ReadDbContext _readDb;
    private readonly WriteDbContext _writeDb;

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        var lastWriteTime = await _writeDb.Claims
            .MaxAsync(c => (DateTime?)c.ProcessedDate, cancellationToken)
            ?? DateTime.UtcNow;

        var lastReadUpdate = await _readDb.ProviderRemittanceReadModel
            .MaxAsync(p => (DateTime?)p.LastUpdated, cancellationToken)
            ?? DateTime.UtcNow;

        var lag = lastWriteTime - lastReadUpdate;

        if (lag.TotalSeconds > 5)
        {
            return HealthCheckResult.Degraded(
                $"Projection lag: {lag.TotalSeconds:F1} seconds");
        }

        return HealthCheckResult.Healthy(
            $"Projection lag: {lag.TotalMilliseconds:F0} ms");
    }
}
```

**Success Criteria**:
- Projection lag: < 500ms (p99)
- Event delivery: 100% (with retry)
- Idempotency: No duplicate processing

