#### Phase 3: Multiple Read Models (6-8 weeks)

**Goal**: Implement specialized read models for different query patterns

**Activities**:
1. Add Elasticsearch for full-text search
2. Add MongoDB for mobile API
3. Add Redis for caching
4. Implement query routing

**Implementation**:
```csharp
// Query API with routing to specialized read models
[ApiController]
[Route("api/providers")]
public class ProviderQueryController : ControllerBase
{
    private readonly SqlReadRepository _sqlRepo;
    private readonly ElasticsearchClient _searchClient;
    private readonly MongoRepository _mongoRepo;
    private readonly ICacheService _cache;

    // Relational query - use SQL read model
    [HttpGet("{providerId}/remittances")]
    public async Task<ActionResult<ProviderRemittanceView>> GetRemittances(
        Guid providerId)
    {
        var cacheKey = $"provider-remittance:{providerId}";

        // Try cache first
        var cached = await _cache.GetAsync<ProviderRemittanceView>(cacheKey);
        if (cached != null)
            return Ok(cached);

        // Query SQL read model
        var view = await _sqlRepo.GetProviderRemittanceAsync(providerId);

        // Cache for 5 minutes
        await _cache.SetAsync(cacheKey, view, TimeSpan.FromMinutes(5));

        return Ok(view);
    }

    // Full-text search - use Elasticsearch
    [HttpGet("search")]
    public async Task<ActionResult<IEnumerable<ProviderSearchResult>>> Search(
        [FromQuery] string query,
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 20)
    {
        var searchRequest = new SearchRequest<ProviderSearchDocument>
        {
            Query = new MultiMatchQuery
            {
                Query = query,
                Fields = new[] { "providerName^2", "taxId", "address" },
                Fuzziness = Fuzziness.Auto
            },
            From = (page - 1) * pageSize,
            Size = pageSize
        };

        var response = await _searchClient.SearchAsync<ProviderSearchDocument>(
            searchRequest);

        var results = response.Documents.Select(d => new ProviderSearchResult
        {
            ProviderId = d.ProviderId,
            ProviderName = d.ProviderName,
            TaxId = d.TaxId,
            Relevance = d.Score
        });

        return Ok(results);
    }

    // Mobile API - use MongoDB for low-latency document access
    [HttpGet("{providerId}/mobile")]
    public async Task<ActionResult<ProviderMobileView>> GetMobileView(
        Guid providerId)
    {
        // MongoDB document optimized for mobile app
        var view = await _mongoRepo.GetProviderMobileViewAsync(providerId);

        if (view == null)
            return NotFound();

        return Ok(view);
    }
}

// Elasticsearch projection
public class ProviderSearchProjection : BackgroundService
{
    private readonly IServiceBusClient _serviceBus;
    private readonly ElasticsearchClient _searchClient;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await _serviceBus.SubscribeAsync<ProviderUpdatedEvent>(
            async (evt, cancellationToken) =>
            {
                await IndexProvider(evt);
            },
            stoppingToken);
    }

    private async Task IndexProvider(ProviderUpdatedEvent evt)
    {
        var document = new ProviderSearchDocument
        {
            ProviderId = evt.ProviderId,
            ProviderName = evt.ProviderName,
            TaxId = evt.TaxId,
            Address = evt.Address,
            City = evt.City,
            State = evt.State,
            ZipCode = evt.ZipCode,
            LastUpdated = DateTime.UtcNow
        };

        await _searchClient.IndexAsync(document, idx => idx
            .Index("providers")
            .Id(evt.ProviderId.ToString()));
    }
}

// MongoDB projection for mobile API
public class ProviderMobileProjection : BackgroundService
{
    private readonly IServiceBusClient _serviceBus;
    private readonly IMongoCollection<ProviderMobileView> _collection;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        // Subscribe to multiple events
        await Task.WhenAll(
            _serviceBus.SubscribeAsync<ProviderUpdatedEvent>(
                async (evt, ct) => await UpdateProviderDocument(evt), stoppingToken),
            _serviceBus.SubscribeAsync<ClaimProcessedEvent>(
                async (evt, ct) => await UpdateClaimSummary(evt), stoppingToken)
        );
    }

    private async Task UpdateProviderDocument(ProviderUpdatedEvent evt)
    {
        var filter = Builders<ProviderMobileView>.Filter.Eq(p => p.ProviderId, evt.ProviderId);

        var update = Builders<ProviderMobileView>.Update
            .Set(p => p.ProviderName, evt.ProviderName)
            .Set(p => p.Address, $"{evt.Address}, {evt.City}, {evt.State} {evt.ZipCode}")
            .Set(p => p.LastUpdated, DateTime.UtcNow);

        await _collection.UpdateOneAsync(
            filter, update, new UpdateOptions { IsUpsert = true });
    }

    private async Task UpdateClaimSummary(ClaimProcessedEvent evt)
    {
        var filter = Builders<ProviderMobileView>.Filter.Eq(p => p.ProviderId, evt.ProviderId);

        var update = Builders<ProviderMobileView>.Update
            .Inc(p => p.RecentClaimCount, 1)
            .Inc(p => p.TotalClaimAmount, evt.Amount)
            .Set(p => p.LastClaimDate, evt.ProcessedDate);

        await _collection.UpdateOneAsync(filter, update);
    }
}
```

**Success Criteria**:
- Search queries: < 100ms (vs. 3s SQL LIKE queries)
- Mobile API: < 50ms (p95)
- Cache hit rate: > 80%

