// Comprehensive monitoring
public class CqrsMetricsCollector
{
    private readonly IMetricsRegistry _metrics;

    public CqrsMetricsCollector(IMetricsRegistry metrics)
    {
        _metrics = metrics;

        // Command metrics
        _metrics.Counter("cqrs_commands_total", "Total commands processed");
        _metrics.Counter("cqrs_commands_failed", "Failed commands");
        _metrics.Histogram("cqrs_command_duration_ms", "Command processing duration");

        // Query metrics
        _metrics.Counter("cqrs_queries_total", "Total queries processed");
        _metrics.Histogram("cqrs_query_duration_ms", "Query processing duration");
        _metrics.Counter("cqrs_cache_hits", "Cache hits");
        _metrics.Counter("cqrs_cache_misses", "Cache misses");

        // Projection metrics
        _metrics.Gauge("cqrs_projection_lag_seconds", "Projection lag in seconds");
        _metrics.Counter("cqrs_events_processed", "Total events processed");
        _metrics.Counter("cqrs_events_failed", "Failed event processing");
        _metrics.Counter("cqrs_duplicate_events", "Duplicate events detected");
    }

    public void RecordCommandDuration(string commandType, double durationMs)
    {
        _metrics.RecordHistogram("cqrs_command_duration_ms", durationMs,
            new Dictionary<string, string> { { "command_type", commandType } });
    }

    public void RecordQueryDuration(string queryType, double durationMs, bool cacheHit)
    {
        _metrics.RecordHistogram("cqrs_query_duration_ms", durationMs,
            new Dictionary<string, string> { { "query_type", queryType } });

        if (cacheHit)
            _metrics.IncrementCounter("cqrs_cache_hits");
        else
            _metrics.IncrementCounter("cqrs_cache_misses");
    }

    public void RecordProjectionLag(string projectionName, double lagSeconds)
    {
        _metrics.SetGauge("cqrs_projection_lag_seconds", lagSeconds,
            new Dictionary<string, string> { { "projection", projectionName } });
    }
}

// Distributed tracing
public class TracedCommandHandler<TCommand> : ICommandHandler<TCommand>
    where TCommand : ICommand
{
    private readonly ICommandHandler<TCommand> _inner;
    private readonly ITracer _tracer;

    public async Task<CommandResult> HandleAsync(TCommand command)
    {
        using var span = _tracer.StartSpan($"Command.{typeof(TCommand).Name}");
        span.SetTag("command.id", command.CommandId.ToString());
        span.SetTag("command.type", typeof(TCommand).Name);

        try
        {
            var result = await _inner.HandleAsync(command);
            span.SetTag("result.success", result.Success);
            return result;
        }
        catch (Exception ex)
        {
            span.SetTag("error", true);
            span.Log(new Dictionary<string, object>
            {
                { "event", "error" },
                { "error.kind", ex.GetType().Name },
                { "message", ex.Message },
                { "stack", ex.StackTrace }
            });
            throw;
        }
    }
}

// Projection replay capability
public class ProjectionRebuilder
{
    private readonly IEventStore _eventStore;
    private readonly ReadDbContext _readDb;
    private readonly ILogger<ProjectionRebuilder> _logger;

    public async Task RebuildProjection(
        string projectionName,
        DateTime? fromDate = null,
        CancellationToken cancellationToken = default)
    {
        _logger.LogInformation(
            "Starting projection rebuild: {ProjectionName} from {FromDate}",
            projectionName, fromDate ?? DateTime.MinValue);

        // Clear existing projection data
        await ClearProjection(projectionName);

        // Replay events
        var startPosition = fromDate?.Ticks ?? 0;
        await foreach (var evt in _eventStore.ReadEventsAsync(
            startPosition, cancellationToken))
        {
            try
            {
                await ApplyEvent(projectionName, evt);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex,
                    "Error replaying event {EventId} for projection {ProjectionName}",
                    evt.EventId, projectionName);
                throw;
            }
        }

        _logger.LogInformation(
            "Completed projection rebuild: {ProjectionName}",
            projectionName);
    }

    private async Task ClearProjection(string projectionName)
    {
        switch (projectionName)
        {
            case "ProviderRemittance":
                await _readDb.Database.ExecuteSqlRawAsync(
                    "TRUNCATE TABLE ProviderRemittanceReadModel");
                break;
            // Other projections...
        }
    }

    private async Task ApplyEvent(string projectionName, DomainEvent evt)
    {
        // Route event to appropriate projection handler
        // Implementation depends on projection architecture
    }
}

// Operational dashboard
[ApiController]
[Route("api/operations/cqrs")]
public class CqrsOperationsController : ControllerBase
{
    private readonly IProjectionHealthService _health;
    private readonly IMetricsRegistry _metrics;

    [HttpGet("health")]
    public async Task<ActionResult<CqrsHealthStatus>> GetHealth()
    {
        var projectionHealth = await _health.GetAllProjectionHealthAsync();

        return Ok(new CqrsHealthStatus
        {
            OverallStatus = projectionHealth.All(p => p.IsHealthy) ? "Healthy" : "Degraded",
            Projections = projectionHealth,
            Metrics = new
            {
                CommandsProcessed = _metrics.GetCounter("cqrs_commands_total"),
                QueriesProcessed = _metrics.GetCounter("cqrs_queries_total"),
                CacheHitRate = CalculateCacheHitRate(),
                AverageProjectionLag = CalculateAverageProjectionLag()
            }
        });
    }

    [HttpPost("projections/{projectionName}/rebuild")]
    public async Task<ActionResult> RebuildProjection(
        string projectionName,
        [FromQuery] DateTime? fromDate)
    {
        // Trigger projection rebuild
        await _health.RebuildProjectionAsync(projectionName, fromDate);

        return Accepted(new
        {
            Message = $"Projection rebuild started: {projectionName}",
            EstimatedDuration = "10-30 minutes"
        });
    }
}
```

**Success Criteria**:
- Monitoring: Complete visibility into command/query/projection metrics
- Alerting: Automatic alerts for lag > 5s or error rate > 1%
- Recovery: Projection rebuild completes in < 30 minutes
- Documentation: Runbooks for common operational scenarios

