public class ProcessClaimCommandHandler {
    private final ClaimRepository writeRepository;
    private final KafkaTemplate<String, DomainEvent> eventPublisher;
    private final Logger logger = LoggerFactory.getLogger(getClass());

    public CommandResult handle(ProcessClaimCommand command) {
        // Validate business rules
        Provider provider = writeRepository.findProviderById(command.getProviderId())
            .orElseThrow(() -> new BusinessException("Provider not found"));

        if (!provider.isActive()) {
            return CommandResult.failure("Provider is not active");
        }

        // Execute business logic
        Claim claim = new Claim();
        claim.setClaimId(command.getClaimId());
        claim.setProviderId(command.getProviderId());
        claim.setMemberId(command.getMemberId());
        claim.setAmount(command.getAmount());
        claim.setServiceDate(command.getServiceDate());
        claim.setProcessedDate(LocalDateTime.now());
        claim.setStatus(ClaimStatus.PROCESSED);

        writeRepository.save(claim);

        // Publish domain event
        ClaimProcessedEvent event = new ClaimProcessedEvent();
        event.setEventId(UUID.randomUUID());
        event.setClaimId(claim.getClaimId());
        event.setProviderId(claim.getProviderId());
        event.setMemberId(claim.getMemberId());
        event.setAmount(claim.getAmount());
        event.setProcessedDate(claim.getProcessedDate());
        event.setTimestamp(LocalDateTime.now());

        eventPublisher.send("domain-events", event.getEventId().toString(), event);

        logger.info("Claim processed: {}, Provider: {}, Amount: {}",
            claim.getClaimId(), claim.getProviderId(), claim.getAmount());

        return CommandResult.success(claim.getClaimId());
    }
}

