public class GetProviderRemittancesQueryHandler {
    private final ProviderRemittanceReadRepository readRepository;
    private final RedisTemplate<String, ProviderRemittanceView> cacheTemplate;
    private final Logger logger = LoggerFactory.getLogger(getClass());

    public ProviderRemittanceView handle(GetProviderRemittancesQuery query) {
        String cacheKey = "provider-remittance:" + query.getProviderId();

        // Try cache first
        ProviderRemittanceView cached = cacheTemplate.opsForValue().get(cacheKey);
        if (cached != null) {
            logger.debug("Cache hit: {}", cacheKey);
            return cached;
        }

        // Query read model
        ProviderRemittanceView view = readRepository.findByProviderId(query.getProviderId())
            .orElse(null);

        if (view != null) {
            // Cache for 5 minutes
            cacheTemplate.opsForValue().set(cacheKey, view, 5, TimeUnit.MINUTES);
        }

        return view;
    }
}

// Projection service (Kafka consumer)
@Service
public class ProviderRemittanceProjectionService {
    private final ProviderRemittanceReadRepository readRepository;
    private final ProcessedEventRepository processedEvents;
    private final Logger logger = LoggerFactory.getLogger(getClass());

    @KafkaListener(topics = "domain-events", groupId = "provider-remittance-projection")
    public void handleEvent(ConsumerRecord<String, String> record) {
        String eventType = record.headers().lastHeader("EventType").value().toString();
        String json = record.value();

        logger.info("Processing event: {}, Offset: {}", eventType, record.offset());

        try {
            switch (eventType) {
                case "ClaimProcessedEvent":
                    ClaimProcessedEvent claimEvent =
                        objectMapper.readValue(json, ClaimProcessedEvent.class);
                    updateFromClaimProcessed(claimEvent);
                    break;

                case "RemittanceGeneratedEvent":
                    RemittanceGeneratedEvent remittanceEvent =
                        objectMapper.readValue(json, RemittanceGeneratedEvent.class);
                    updateFromRemittanceGenerated(remittanceEvent);
                    break;

                default:
                    logger.debug("Event type {} not handled by this projection", eventType);
                    break;
            }
        } catch (Exception ex) {
            logger.error("Error processing event: {}", eventType, ex);
            throw new RuntimeException(ex);  // Will trigger Kafka retry
        }
    }

    @Transactional
    private void updateFromClaimProcessed(ClaimProcessedEvent event) {
        // Idempotency check
        String eventId = event.getEventId().toString();
        if (processedEvents.existsById(eventId)) {
            logger.info("Event already processed: {}", eventId);
            return;
        }

        // Update read model
        ProviderRemittanceReadModel provider = readRepository
            .findById(event.getProviderId())
            .orElseGet(() -> {
                ProviderRemittanceReadModel newProvider = new ProviderRemittanceReadModel();
                newProvider.setProviderId(event.getProviderId());
                newProvider.setRemittanceCount(0);
                newProvider.setTotalAmount(BigDecimal.ZERO);
                return newProvider;
            });

        provider.setRemittanceCount(provider.getRemittanceCount() + 1);
        provider.setTotalAmount(provider.getTotalAmount().add(event.getAmount()));
        provider.setLastUpdated(LocalDateTime.now());

        readRepository.save(provider);

        // Track processed event
        ProcessedEvent processedEvent = new ProcessedEvent();
        processedEvent.setEventId(eventId);
        processedEvent.setEventType("ClaimProcessedEvent");
        processedEvent.setProcessedAt(LocalDateTime.now());
        processedEvents.save(processedEvent);

        logger.info("Updated read model for provider {} from event {}",
            event.getProviderId(), event.getEventId());
    }
}

